import type { Edge, Graph, Group, Site } from '../types'

export const SOURCE_GLOBS = ['*.py', '*.ts', '*.tsx', '*.js', '*.jsx', '*.mjs', '*.cjs']

/** Lines `git grep -E` matches as possible imports, in POSIX classes so every git build reads them. */
export const IMPORT_PATTERN =
  '^[[:space:]]*(import|from)[[:space:]]|require\\(|^[[:space:]]*export[[:space:]].*[[:space:]]from[[:space:]]'

/** Lines `git grep -E` matches as possible definitions. */
export const SYMBOL_PATTERN =
  '^[[:space:]]*(async[[:space:]]+)?def[[:space:]]+[A-Za-z_]|^[[:space:]]*class[[:space:]]+[A-Za-z_]|function[[:space:]]*\\*?[[:space:]]+[A-Za-z_$]|^[[:space:]]*(export[[:space:]]+)?(const|let)[[:space:]]+[A-Za-z_$][A-Za-z0-9_$]*[[:space:]]*=[[:space:]]*(async[[:space:]]*)?(\\(|function|[A-Za-z_$][A-Za-z0-9_$]*[[:space:]]*=>)'

/** The same two patterns as JavaScript expressions, for folders searched without git. */
export const IMPORT_RE = /^\s*(import|from)\s|require\(|^\s*export\s.*\sfrom\s/
export const SYMBOL_RE =
  /^\s*(async\s+)?def\s+[A-Za-z_]|^\s*class\s+[A-Za-z_]|function\s*\*?\s+[A-Za-z_$]|^\s*(export\s+)?(const|let)\s+[A-Za-z_$][\w$]*\s*=\s*(async\s*)?(\(|function|[A-Za-z_$][\w$]*\s*=>)/

export const SOURCE_EXTENSIONS = ['.py', '.ts', '.tsx', '.js', '.jsx', '.mjs', '.cjs']

/** Folders a walk without git never enters: dependencies, environments, caches and build output. */
export const SKIPPED_DIRS = new Set([
  'node_modules', 'venv', '.venv', 'env', '.env', '__pycache__', 'dist', 'build', 'out', 'target', 'coverage',
  'site-packages', '.git', '.hg', '.svn', '.next', '.nuxt', '.tox', '.mypy_cache', '.pytest_cache', '.ruff_cache',
  '.idea', '.vscode', '.cache', '.turbo', 'vendor',
])

export function isSource(name: string): boolean {
  return SOURCE_EXTENSIONS.some(ext => name.endsWith(ext)) && !name.endsWith('.d.ts') && !name.endsWith('.min.js')
}

/** What `git grep -n -E` prints, produced from texts held in memory. */
export function grepTexts(texts: ReadonlyMap<string, string>, pattern: RegExp): string {
  const out: string[] = []
  for (const [path, text] of texts) {
    text.split('\n').forEach((line, index) => {
      if (pattern.test(line)) out.push(`${path}:${index + 1}:${line}`)
    })
  }
  return out.join('\n')
}

/** What `git grep -n -o -E` prints: each match on its own line. */
export function grepMatches(texts: ReadonlyMap<string, string>, pattern: RegExp): string {
  const global = new RegExp(pattern.source, pattern.flags.includes('g') ? pattern.flags : `${pattern.flags}g`)
  const out: string[] = []
  for (const [path, text] of texts) {
    text.split('\n').forEach((line, index) => {
      for (const match of line.matchAll(global)) out.push(`${path}:${index + 1}:${match[0]}`)
    })
  }
  return out.join('\n')
}

/** What `git grep -c ''` prints: the line count of each file. */
export function countTexts(texts: ReadonlyMap<string, string>): string {
  return [...texts].map(([path, text]) => `${path}:${text.split('\n').length - (text.endsWith('\n') ? 1 : 0)}`).join('\n')
}

export const MAX_FILES = 4000
const MAX_GROUP_PATHS = 60
const MAX_GROUPS = 80
const MAX_EDGES = 1000
const GROUP_DEPTH = 3
const JS_EXTENSIONS = ['.ts', '.tsx', '.js', '.jsx', '.mjs', '.cjs']

export type FileImports = Map<string, Set<string>>
export type SymbolIndex = Map<string, Site[]>

/** Everything a scan learned: the map for the pane, and the indexes later lookups use. */
export type Scan = { graph: Graph; imports: FileImports; symbols: SymbolIndex }

export function isPython(path: string): boolean {
  return path.endsWith('.py')
}

/** The folder a file is drawn under: its directory, cut to GROUP_DEPTH levels. */
export function groupOf(path: string): string {
  const parts = path.split('/').slice(0, -1)
  return parts.length === 0 ? '(root)' : parts.slice(0, GROUP_DEPTH).join('/')
}

/** Splits one `git grep -n` line into file, line number and text. */
export function grepLine(line: string): { file: string; line: number; text: string } | null {
  const match = /^(.+?):(\d+):(.*)$/.exec(line)
  if (match === null) return null
  return { file: match[1] ?? '', line: Number(match[2]), text: match[3] ?? '' }
}

function normalize(parts: readonly string[]): string {
  const out: string[] = []
  for (const part of parts) {
    if (part === '' || part === '.') continue
    if (part === '..') out.pop()
    else out.push(part)
  }
  return out.join('/')
}

function dirOf(path: string): string[] {
  return path.split('/').slice(0, -1)
}

/** Finds the repo file a dotted Python module names, also under a prefix such as src/. */
function pythonFile(dotted: string, base: readonly string[], files: ReadonlySet<string>, bySuffix: Map<string, string>): string | null {
  const stem = normalize([...base, ...dotted.split('.')])
  for (const candidate of [`${stem}.py`, `${stem}/__init__.py`]) {
    if (files.has(candidate)) return candidate
    if (base.length === 0) {
      const found = bySuffix.get(candidate)
      if (found !== undefined) return found
    }
  }
  return null
}

/** The repo files one Python import line brings in. */
export function resolvePython(from: string, text: string, files: ReadonlySet<string>, bySuffix: Map<string, string>): string[] {
  const out: string[] = []
  const fromImport = /^\s*from\s+(\.*)([\w.]*)\s+import\s+(.+)$/.exec(text)
  if (fromImport !== null) {
    const dots = (fromImport[1] ?? '').length
    const module = fromImport[2] ?? ''
    const base = dots === 0 ? [] : dirOf(from).slice(0, Math.max(0, dirOf(from).length - (dots - 1)))
    const whole = module === '' ? null : pythonFile(module, base, files, bySuffix)
    if (whole !== null) out.push(whole)
    const names = (fromImport[3] ?? '').replace(/[()]/g, '').split(',')
    for (const name of names) {
      const bare = name.trim().split(/\s+/)[0] ?? ''
      if (!/^\w+$/.test(bare)) continue
      const sub = pythonFile(module === '' ? bare : `${module}.${bare}`, base, files, bySuffix)
      if (sub !== null) out.push(sub)
    }
    return out
  }
  const plain = /^\s*import\s+([\w.]+(?:\s*,\s*[\w.]+)*)/.exec(text)
  if (plain !== null) {
    for (const module of (plain[1] ?? '').split(',')) {
      const found = pythonFile(module.trim(), [], files, bySuffix)
      if (found !== null) out.push(found)
    }
  }
  return out
}

/** The repo files one JS or TS import line brings in; package imports are left out. */
export function resolveJs(from: string, text: string, files: ReadonlySet<string>): string[] {
  const out: string[] = []
  const pattern = /(?:\bfrom\s*|\bimport\s*\(?\s*|\brequire\(\s*)['"]([^'"]+)['"]/g
  for (const match of text.matchAll(pattern)) {
    const spec = match[1] ?? ''
    if (!spec.startsWith('.')) continue
    const stem = normalize([...dirOf(from), ...spec.split('/')])
    const candidates = [
      stem,
      ...JS_EXTENSIONS.map(ext => `${stem}${ext}`),
      ...JS_EXTENSIONS.map(ext => `${stem}/index${ext}`),
      stem.replace(/\.js$/, '.ts'),
      stem.replace(/\.js$/, '.tsx'),
    ]
    const found = candidates.find(candidate => files.has(candidate))
    if (found !== undefined) out.push(found)
  }
  return out
}

/** The name a definition line declares, or null. */
export function symbolName(text: string): string | null {
  const patterns = [
    /^\s*(?:async\s+)?def\s+([A-Za-z_]\w*)/,
    /^\s*(?:export\s+)?(?:default\s+)?(?:abstract\s+)?class\s+([A-Za-z_$][\w$]*)/,
    /function\s*\*?\s+([A-Za-z_$][\w$]*)/,
    /^\s*(?:export\s+)?(?:const|let)\s+([A-Za-z_$][\w$]*)\s*=/,
  ]
  for (const pattern of patterns) {
    const match = pattern.exec(text)
    if (match?.[1] !== undefined) return match[1]
  }
  return null
}

/** Height of each folder in the dependency order, cycles broken where they close. */
export function levels(ids: readonly string[], edges: readonly Edge[]): Map<string, number> {
  const out = new Map<string, string[]>()
  for (const edge of edges) out.set(edge.from, [...(out.get(edge.from) ?? []), edge.to])
  const memo = new Map<string, number>()
  const visiting = new Set<string>()
  const level = (id: string): number => {
    const known = memo.get(id)
    if (known !== undefined) return known
    if (visiting.has(id)) return 0
    visiting.add(id)
    const deps = out.get(id) ?? []
    const value = deps.length === 0 ? 0 : 1 + Math.max(...deps.map(level))
    visiting.delete(id)
    memo.set(id, value)
    return value
  }
  return new Map(ids.map(id => [id, level(id)]))
}

/** Builds the map and indexes from the four git outputs a scan collects, or their in-memory equivalents. */
export function buildScan(root: string, fileList: string, lineCounts: string, importLines: string, symbolLines: string, isGit = true): Scan {
  const fileNames = fileList.split('\n').filter(Boolean)
  const isTruncated = fileNames.length > MAX_FILES
  const files = new Set(fileNames.slice(0, MAX_FILES))
  const bySuffix = new Map<string, string>()
  for (const file of files) {
    const parts = file.split('/')
    for (let start = 1; start < parts.length; start += 1) {
      const suffix = parts.slice(start).join('/')
      if (!bySuffix.has(suffix)) bySuffix.set(suffix, file)
    }
  }

  const lines = new Map<string, number>()
  for (const row of lineCounts.split('\n')) {
    const match = /^(.+):(\d+)$/.exec(row)
    if (match !== null && files.has(match[1] ?? '')) lines.set(match[1] ?? '', Number(match[2]))
  }

  const imports: FileImports = new Map()
  for (const row of importLines.split('\n')) {
    const hit = grepLine(row)
    if (hit === null || !files.has(hit.file)) continue
    const targets = isPython(hit.file) ? resolvePython(hit.file, hit.text, files, bySuffix) : resolveJs(hit.file, hit.text, files)
    for (const target of targets) {
      if (target === hit.file) continue
      const set = imports.get(hit.file) ?? new Set<string>()
      set.add(target)
      imports.set(hit.file, set)
    }
  }

  const symbols: SymbolIndex = new Map()
  const symbolCount = new Map<string, number>()
  for (const row of symbolLines.split('\n')) {
    const hit = grepLine(row)
    if (hit === null || !files.has(hit.file)) continue
    const name = symbolName(hit.text)
    if (name === null) continue
    symbols.set(name, [...(symbols.get(name) ?? []), { symbol: name, file: hit.file, line: hit.line, isKnown: true }])
    symbolCount.set(groupOf(hit.file), (symbolCount.get(groupOf(hit.file)) ?? 0) + 1)
  }

  const groupFiles = new Map<string, string[]>()
  for (const file of files) groupFiles.set(groupOf(file), [...(groupFiles.get(groupOf(file)) ?? []), file])

  const edgeCount = new Map<string, number>()
  for (const [from, targets] of imports) {
    for (const to of targets) {
      const key = `${groupOf(from)}\u0000${groupOf(to)}`
      if (groupOf(from) !== groupOf(to)) edgeCount.set(key, (edgeCount.get(key) ?? 0) + 1)
    }
  }
  const edges: Edge[] = [...edgeCount]
    .map(([key, count]) => {
      const [from = '', to = ''] = key.split('\u0000')
      return { from, to, count }
    })
    .sort((a, b) => b.count - a.count)
    .slice(0, MAX_EDGES)

  const byLines = [...groupFiles.keys()].sort(
    (a, b) => (groupFiles.get(b)?.length ?? 0) - (groupFiles.get(a)?.length ?? 0),
  )
  const kept = new Set(byLines.slice(0, MAX_GROUPS))
  const keptEdges = edges.filter(edge => kept.has(edge.from) && kept.has(edge.to))
  const heights = levels([...kept], keptEdges)
  const groups: Group[] = [...kept]
    .map(id => ({
      id,
      files: groupFiles.get(id)?.length ?? 0,
      lines: (groupFiles.get(id) ?? []).reduce((sum, file) => sum + (lines.get(file) ?? 0), 0),
      symbols: symbolCount.get(id) ?? 0,
      level: heights.get(id) ?? 0,
      paths: [...(groupFiles.get(id) ?? [])].sort().slice(0, MAX_GROUP_PATHS),
    }))
    .sort((a, b) => b.level - a.level || a.id.localeCompare(b.id))

  return {
    graph: { root, isGit, files: files.size, groups, edges: keptEdges, isTruncated: isTruncated || kept.size < groupFiles.size },
    imports,
    symbols,
  }
}

/** Files outside `changed` that import any file in it. */
export function dependentsOf(changed: ReadonlySet<string>, imports: FileImports): string[] {
  const out: string[] = []
  for (const [from, targets] of imports) {
    if (changed.has(from)) continue
    if ([...targets].some(target => changed.has(target))) out.push(from)
  }
  return out.sort()
}

export function shortCount(value: number): string {
  return value >= 1000 ? `${(value / 1000).toFixed(1)}k` : String(value)
}

files.hooks/theme.ts:
/**
 * One palette for every view: soft, saturated tones that read on dark terminals and in the desktop app.
 * ok/bad/warn carry meaning everywhere (added/passing, removed/failing, modified/warning).
 */
export const C = {
  ok: '#34D399',
  bad: '#F87171',
  warn: '#FBBF24',
  live: '#22D3EE',
  accent: '#A78BFA',
  blue: '#60A5FA',
  pink: '#F472B6',
  line: '#475569',
  soft: '#94A3B8',
  text: '#E2E8F0',
  /** Dark text on a filled pill. */
  ink: '#1E1B2E',
  /** The fill behind a quiet chip. */
  chip: '#334155',
} as const

const NAMED: Record<string, string> = {
  green: C.ok,
  red: C.bad,
  yellow: C.warn,
  cyan: C.live,
  magenta: C.accent,
  blue: C.blue,
  gray: C.line,
}

/** The palette's tone for a colour name the shared helpers use ('green', 'red', ...); other values pass through. */
export function hue(name: string | undefined): string | undefined {
  return name === undefined ? undefined : (NAMED[name] ?? name)
}

/** A compact gauge of `width` cells: ▰ for the used share, ▱ for the rest. */
export function pill(percent: number, width: number): { used: string; left: string } {
  const filled = Math.max(0, Math.min(width, Math.round((Math.min(100, Math.max(0, percent)) / 100) * width)))
  return { used: '▰'.repeat(filled), left: '▱'.repeat(width - filled) }
}

/** A git-style change bar: green cells for added lines and red for removed, scaled so `most` fills `width`. */
export function diffstat(added: number, removed: number, most: number, width: number): { plus: string; minus: string } {
  const total = added + removed
  if (total === 0 || most <= 0) return { plus: '', minus: '' }
  const cells = Math.max(1, Math.round((Math.min(total, most) / most) * width))
  const plus = added === 0 ? 0 : removed === 0 ? cells : Math.max(1, Math.round((added / total) * cells))
  return { plus: '▮'.repeat(plus), minus: '▮'.repeat(Math.max(0, cells - plus)) }
}

/** Cuts text to `width` cells, keeping the end: a path keeps its file name. */
export function tail(text: string, width: number): string {
  if (width <= 1) return text.slice(-Math.max(0, width))
  return text.length <= width ? text : `…${text.slice(text.length - width + 1)}`
}

/** Cuts text to `width` cells, keeping the start. */
export function head(text: string, width: number): string {
  if (width <= 1) return text.slice(0, Math.max(0, width))
  return text.length <= width ? text : `${text.slice(0, width - 1)}…`
}

/** One line of a prompt, without runs of white space. */
export function oneLine(text: string): string {
  return text.replace(/\s+/g, ' ').trim()
}

/** True when a drawn tree holds any visible text: whether another mod drew something in the band. */
export function hasContent(node: unknown): boolean {
  if (typeof node === 'string') return node.trim() !== ''
  if (typeof node === 'number') return true
  if (Array.isArray(node)) return node.some(hasContent)
  if (node !== null && typeof node === 'object') {
    const element = node as { children?: unknown; props?: { label?: unknown } }
    if (typeof element.props?.label === 'string' && element.props.label.trim() !== '') return true
    return hasContent(element.children)
  }
  return false
}

files.hooks/trace.ts:
import type { Lane, Step, StepStatus, Turn } from '../types'

export const MAX_TURNS = 5
const MAX_STEPS = 200
const MAX_OUTPUT = 240

function basename(path: string): string {
  return path.split('/').filter(Boolean).pop() ?? path
}

function firstString(input: Record<string, unknown>): string {
  const found = Object.values(input).find(value => typeof value === 'string')
  return typeof found === 'string' ? found : ''
}

/** One short line saying what a tool call is about. */
export function summarize(tool: string, input: Record<string, unknown>): string {
  const get = (key: string): string => (typeof input[key] === 'string' ? (input[key] as string) : '')
  switch (tool) {
    case 'Bash':
      return get('command')
    case 'Read':
    case 'Edit':
    case 'Write':
      return basename(get('file_path'))
    case 'NotebookEdit':
      return basename(get('notebook_path'))
    case 'Grep':
    case 'Glob':
      return get('pattern')
    case 'WebFetch':
      return get('url')
    case 'WebSearch':
      return get('query')
    case 'Agent':
      return [get('subagent_type'), get('description')].filter(Boolean).join(': ')
    case 'Skill':
      return get('skill')
    default:
      return firstString(input)
  }
}

export function preview(text: string | undefined): string {
  const lines = (text ?? '').trim().split('\n').slice(0, 3).join('\n')
  return lines.length > MAX_OUTPUT ? `${lines.slice(0, MAX_OUTPUT)}…` : lines
}

export function statusOf(ran: { deny?: string; isError?: true }): StepStatus {
  if (ran.deny !== undefined) return 'denied'
  return ran.isError === true ? 'error' : 'ok'
}

/** Applies a change to the newest turn, creating one when a tool runs before any turn started. */
export function onNewest(turns: readonly Turn[], now: number, change: (turn: Turn) => Turn): Turn[] {
  const newest = turns[turns.length - 1] ?? {
    id: 'earlier',
    prompt: '(before this view opened)',
    startedAt: now,
    status: 'running',
    steps: [],
    lanes: [{ id: 'main', label: 'Main' }],
  }
  return [...turns.slice(0, -1), change(newest)]
}

export function withStep(turn: Turn, step: Step, laneLabel: string): Turn {
  const hasLane = turn.lanes.some(lane => lane.id === step.lane)
  const lanes: Lane[] = hasLane ? turn.lanes : [...turn.lanes, { id: step.lane, label: laneLabel }]
  return { ...turn, lanes, steps: [...turn.steps, step].slice(-MAX_STEPS) }
}

export function withStepChange(turns: readonly Turn[], id: string, change: Partial<Step>): Turn[] {
  return turns.map(turn =>
    turn.steps.some(step => step.id === id)
      ? { ...turn, steps: turn.steps.map(step => (step.id === id ? { ...step, ...change } : step)) }
      : turn,
  )
}

export function relabel(turns: readonly Turn[], laneId: string, label: string): Turn[] {
  return turns.map(turn => ({
    ...turn,
    lanes: turn.lanes.some(lane => lane.id === laneId)
      ? turn.lanes.map(lane => (lane.id === laneId ? { ...lane, label } : lane))
      : turn.lanes,
  }))
}

export function seconds(ms: number): string {
  if (ms < 1000) return `${Math.max(0, Math.round(ms))}ms`
  if (ms < 60_000) return `${(ms / 1000).toFixed(1)}s`
  const minutes = Math.floor(ms / 60_000)
  return `${minutes}m${String(Math.round((ms % 60_000) / 1000)).padStart(2, '0')}s`
}

/** Time the main lane spent outside tool calls: the model reading, deciding and writing. */
export function modelTime(turn: Turn, now: number): number {
  const end = turn.endedAt ?? now
  const spans = turn.steps
    .filter(step => step.lane === 'main')
    .map(step => [step.startedAt, step.endedAt ?? now] as const)
    .sort((a, b) => a[0] - b[0])
  let busy = 0
  let reach = turn.startedAt
  for (const [start, stop] of spans) {
    const from = Math.max(start, reach)
    if (stop > from) busy += stop - from
    reach = Math.max(reach, stop)
  }
  return Math.max(0, end - turn.startedAt - busy)
}

/** A waterfall bar: leading spaces then blocks, placed on the turn's time span. */
export function bar(step: Step, turn: Turn, now: number, width: number): { pad: string; fill: string } {
  const span = Math.max(1, (turn.endedAt ?? now) - turn.startedAt)
  const start = Math.min(width - 1, Math.floor(((step.startedAt - turn.startedAt) / span) * width))
  const length = Math.max(1, Math.round((((step.endedAt ?? now) - step.startedAt) / span) * width))
  return { pad: ' '.repeat(Math.max(0, start)), fill: '█'.repeat(Math.min(length, width - start)) }
}

export function colorOf(step: Step, now: number): string {
  if (step.status === 'running') return 'cyan'
  if (step.status === 'error') return 'red'
  if (step.status === 'denied') return 'magenta'
  const took = (step.endedAt ?? now) - step.startedAt
  return took >= 30_000 ? 'red' : took >= 10_000 ? 'yellow' : 'green'
}

export const BADGE: Record<StepStatus, string> = { running: '●', ok: '✓', error: '✗', denied: '⊘' }

/** What a turn's prompt reads as: a background task's notice becomes its one-line summary instead of raw tags. */
export function promptLabel(text: string): string {
  const flat = text.replace(/\s+/g, ' ').trim()
  if (flat === '') return '(continued without a prompt)'
  if (flat.startsWith('<task-notification>')) {
    const summary = /<summary>(.*?)<\/summary>/.exec(flat)?.[1]?.trim()
    return `↻ ${summary === undefined || summary === '' ? 'a background task finished' : summary}`
  }
  return flat.slice(0, 160)
}

